16	lemma ArrayFacts<T>()
17		ensures forall v : array<T>  :: v[..v.Length] == v[..];
18		ensures forall v : array<T>  :: v[0..] == v[..];
19	    ensures forall v : array<T>  :: v[0..v.Length] == v[..];
20	
21		ensures forall v : array<T>  ::|v[0..v.Length]|==v.Length;
22	    ensures forall v : array<T> | v.Length>=1 ::|v[1..v.Length]|==v.Length-1;
23	    
24		ensures forall v : array<T>  ::forall k : nat | k < v.Length :: v[..k+1][..k] == v[..k]
25	  {}
26	
27	method mcountEven(v:array<int>) returns (n:int)
28	requires positive(v[..])
29	ensures  n==CountEven(v[..])
30	{   ArrayFacts<int>(); 
31	
32	 n:=0;
33	 var i:int;
34	 i:=0;
35	 while (i<v.Length)
36	   decreases v.Length - i//write
37	   invariant 0<=i<=v.Length//write
38	 {
39	
40	   if (v[i]%2==0) {n:=n+1;}
41	   i:=i+1;
42	
43	 }
44	 }
